// Arma el registro de firmas del repo como lo dejan dos ramas unidas: una base y dos firmas que enganchan con la MISMA
// línea. `editar` cambia los AC de la segunda sin recalcular su cadena (la edición a mano que se tiene que seguir viendo).
const crypto = require('crypto');
const fs = require('fs');
const w = require(process.env.SKILLS + '/skills/tycon-pipeline/scripts/lib/runtime-waiver.js');
const sha = (s) => crypto.createHash('sha256').update(s).digest('hex').slice(0, 16);
function canon(e) {
  const b = [e.ts, String(e.story), [...e.acs].sort((x, y) => x - y), e.matrixHash, e.approvedBy || null];
  if (e.declHashByAc !== undefined) b.push(Object.keys(e.declHashByAc).sort((x, y) => x - y).map((k) => [Number(k), e.declHashByAc[k]]));
  return JSON.stringify(b);
}
const cuelga = (padre, e) => ({ ...e, chain: sha(padre + canon(e)) });
const d = w.declHashFor('fixture de test', 'T1');
const d2 = w.declHashFor('fixture de test', 'T2');
const base = cuelga('', { ts: '2026-10-07T08:00:00.000Z', story: '9.1', acs: [1], matrixHash: 'm', approvedBy: 'deva', tty: true });
const ramaA = cuelga(base.chain, { ts: '2026-10-07T08:10:00.000Z', story: '9.8', acs: [4], matrixHash: 'm', approvedBy: 'deva', tty: true });
const ramaB = cuelga(base.chain, { ts: '2026-10-07T08:20:00.000Z', story: '9.9', acs: [1, 2], matrixHash: 'm', approvedBy: 'deva', tty: true, declHashByAc: { 1: d, 2: d2 } });
if (process.argv[2] === 'editar') ramaB.ts = '2026-10-07T09:00:00.000Z';
fs.mkdirSync('.tycon', { recursive: true });
fs.writeFileSync('.tycon/runtime-waivers.jsonl', [base, ramaA, ramaB].map((e) => JSON.stringify(e)).join('\n') + '\n');

